import copy
import json

from yaml import safe_load
import logging

from pathlib import Path

from taf.rfrl.csv4all.resources.node.ru_manager.exceptions import RuBlackboxVerificationFailed
from taf.rfrl.csv4all.resources.node.ru_manager.ru_configuration import RuConfiguration
from taf.rfrl.csv4all.resources.node.ru_manager.ru_shell import RmodSshSession
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger

logger = logging.getLogger(__name__)

class RUInterface:
    def __init__(self, ssh_manager, node_rmods: dict, rmod_setup_yaml_path: str= None,
                 smod_ip="192.168.255.129", smod_username="toor4nsn", smod_password="oZPS0POrRieRtu"):
        self.node_all_rmods = node_rmods
        self.ssh_manager = ssh_manager
        self.rmod_connections = {}
        self.rmod_setup = self._read_rmod_data(rmod_setup_yaml_path)
        self.serial_number_path = "/mnt/factory/configs/unit/module_serial_number.txt"
        self.ru_session = RmodSshSession(ssh_manager=self.ssh_manager, smod_ip=smod_ip, username=smod_username,
                                         password=smod_password)
        self.node_supported_rmods = self._get_supported_rmods()
        self.add_rmods_from_yaml_file()

    @staticmethod
    def _read_rmod_data(rmod_setup_yaml_path: str):
        with open(Path(rmod_setup_yaml_path)) as yaml_file:
            yaml_content = safe_load(yaml_file)
            test_logger(f"RU Manager yaml content:\n{json.dumps(yaml_content, indent=4)}", "DEBUG")
            return yaml_content

    def add_rmods_from_yaml_file(self):
        def update_dict(rmod_details_dict: dict, dict_name: dict):
            dict_name["serial_number"] = rmod_details_dict["Serial Number"]
            dict_name["radio_type"] = rmod_details_dict["Module Type"]
            dict_name["rmod_ip"] = rmod_details_dict["Ip Address"]
            dict_name["slave_bts"] = rmod_details_dict.get("Mapped SMOD", "") == "Secondary"
            return dict_name

        all_rmods_defaults = copy.deepcopy(self.rmod_setup.get('All Rmods', {}))
        if all_rmods_defaults:
            for rmod_details in self.node_supported_rmods.values():
                if not rmod_details["Eligible For Reset"]:
                    continue
                radio_name = rmod_details["Module Type"]
                if radio_name.startswith("F"):
                    test_logger(f"[{radio_name}] Radio Modules with telnet interface are not supported", "WARN")
                    continue
                all_rmods_defaults = copy.deepcopy(update_dict(rmod_details, all_rmods_defaults))

                self.rmod_connections[rmod_details["Serial Number"]] = RuConfiguration(**all_rmods_defaults)
        for serial_number, radio_specific_config in self.rmod_setup.items():
            if serial_number == 'All Rmods' or "TEMPLATE" in serial_number:
                continue
            radio_specific_config_copy = copy.deepcopy(radio_specific_config)
            if serial_number in self.rmod_connections:
                self.rmod_connections[serial_number].update_attributes(**radio_specific_config_copy)
            else:
                for rmod_details in self.node_supported_rmods.values():
                    if serial_number == rmod_details["Serial Number"]:
                        radio_specific_config_copy = update_dict(rmod_details, radio_specific_config_copy)
                if radio_specific_config_copy.get("serial_number", None):
                    self.rmod_connections[serial_number] = RuConfiguration(**radio_specific_config_copy)

    def execute_commands_on_rmods(self, fail_on_error: bool = False):
        for rmod_instance in self.rmod_connections.values():
            try:
                if rmod_instance.supported and rmod_instance.commands_after_connect:
                    self.ru_session.execute_command_on_rmods(rmod_instance)
            except Exception as e:
                test_logger(e, "ERROR")
                if fail_on_error:
                    raise

    def add_flags_to_rmods(self):
        for rmod_instance in self.rmod_connections.values():
            try:
                if rmod_instance.supported:
                    if rmod_instance.flags_to_add:
                        self.ru_session.add_flags_on_rmod(rmod_instance)
                    elif rmod_instance.commands_after_connect:
                        self.ru_session.execute_command_on_rmods(rmod_instance)
            except Exception as e:
                test_logger(e, "ERROR")


    def restore_flags_on_rmods(self):
        for rmod_instance in self.rmod_connections.values():
            if rmod_instance.restore_flags and rmod_instance.supported:
                try:
                    self.ru_session.restore_flags_on_rmod(rmod_instance)
                except Exception as e:
                    test_logger(e, "ERROR")

    def _get_supported_rmods(self):
        node_supported_rmods = dict()
        for rmod, rmod_details in self.node_all_rmods.items():
            radio_name = rmod_details["Module Type"]
            if radio_name.startswith("F"):
                test_logger(f"[{radio_name}] Radio Modules with telnet interface are not supported", "WARN")
                continue
            node_supported_rmods.update({rmod:rmod_details})
        return node_supported_rmods

    def get_blackbox_files_from_rmods(self, target_dir: str):
        for rmod_instance in self.rmod_connections.values():
            if rmod_instance.verify_blackbox:
                try:
                    self.ru_session.download_blackbox_from_rmod(rmod_instance=rmod_instance, target_dir=target_dir)
                except Exception as e:
                    test_logger(e, "ERROR")

    def verify_ru_blackbox(self):
        for rmod_instance in self.rmod_connections.values():
            if rmod_instance.verify_blackbox:
                rmod_instance.blackbox.verify_blackbox(rmod_instance.serial_number)
                if rmod_instance.blackbox.blackbox_verification_passed:
                    test_logger(f"[{rmod_instance.serial_number}] Verification RU Blackbox passed")
                else:
                    test_logger(f"[{rmod_instance.serial_number}] Verification RU Blackbox failed", "ERROR")
        if any(not rmod_instance.blackbox.blackbox_verification_passed for rmod_instance in
               self.rmod_connections.values()):
            raise RuBlackboxVerificationFailed()
